#include <stdio.h>
int main() {
int arr []={0,1,2,3,4};
int i=1, *ptr;
ptr =arr+2 ;
printf ("% d", ptr [i]);
printf ("%d", ptr [i+1]);
printf ("%d", ptr[-i]);
printf (“%d", ptr[-i+1]);
return 0;
}
Output -  3412
Explanation:
ptr = arr + 2; sets ptr to point to the third
element of the array arr, which is 2.
ptr[i] is equivalent to *(ptr + i) i.e. value at
index 3 which is 3.
so ptr[i+1] = 4
since ptr=arr+2, which points value at index 2,
so ptr[-i] will give value at index 1 which is 1.
ptr[-i+1] will point to ptr[0] which is
2.Therefore if we want to arrange the print
statements in increasing order it would be
Option B (c,d,a,b).

Statement I: The friend function and the
member functions of a friend class directly
access the private and protected data is true
because A friend class can access private and
protected members of other classes in which it is
declared as a friend. It is sometimes useful to
allow a particular class to access private and
protected members of other classes.
class base {
private:
int private_variable;
protected:
int protected_variable;
public:
base()
{
private_variable = 10;
protected_variable = 99;
}
// friend class declaration
friend class F;
};
// Here, class F is declared as a
// friend inside class base. Therefore,
// F is a friend of class base. Class F
// can access the private and protected members
of
// class base.
class F {
public:
void display(base& t)
{
cout << "The value of Private Variable = "
<< t.private_variable << endl;
cout << "The value of Protected Variable = "
<< t.protected_variable;
}
};
// Driver code
int main()
{
base g;
F fri;
fri.display(g);
return 0;
}
The value of Private Variable = 10
The value of Protected Variable = 99
